Tìm số đo ${x}$, ${y}$ trong hình vẽ.

\choice
{  $x=40^{\circ}$ và $y=107^{\circ}$  }
   { \True   $x=37^{\circ}$ và $y=107^{\circ}$ }
     {   $x=41^{\circ}$ và $y=109^{\circ}$ }
    {   $x=37^{\circ}$ và $y=111^{\circ}$ }
}{
\begin{tikzpicture}
    % Vẽ các điểm của tam giác
    \coordinate [label=left:A] (A) at (0, 0);
    \coordinate [label=above:B] (B) at (-2, 4);
    \coordinate [label=right:C] (C) at (6, 0);
        \coordinate [label=above right:D] (D) at (3, 3/2);
            \coordinate [label=above right:E] (E) at (-4, 10/2);
    % Tạo điểm D nằm giữa B và C


    % Vẽ các cạnh của tam giác
    \draw (A) -- (B) -- (C) -- cycle;
    \draw (A) -- (D);
        \draw (E) -- (B);
    % Đánh dấu điểm D
    \fill (D) circle (1.2pt);
        \fill (A) circle (1.2pt);
            \fill (B) circle (1.2pt);
                \fill (C) circle (1.2pt);
                    \fill (E) circle (1.2pt);
      \node at (0.1,0.3) {$y^{\circ}$};
    \node at (0.9,0.2) {$25^{\circ}$};
        \node at (2.3,1.5) {$62^{\circ}$};
            \node at (5,0.3) {$x^{\circ}$};
                \node at (-2.3,3.7) {$169^{\circ}$};
\end{tikzpicture}
}
\loigiai{
Áp dụng tính chất: Mỗi góc ngoài của một tam giác bằng tổng hai góc trong không kề với nó. $x=37^{\circ}$ và $y=107^{\circ}$.
}\end{ex}

